fixReadingProgressUniqueIndexV2가 sqlite_master의 CREATE TABLE SQL 문자열에 'UNIQUE(user_id, series_id)'가 포함되는지로만 마이그레이션 여부를 판단하는데, SQLite는 공백/줄바꿈 포맷이 달라질 수 있어 탐지에 실패하면 ON CONFLICT(user_id, chapter_id)와 매칭되는 제약이 없어져 진행도 저장이 런타임 에러로 깨질 수 있습니다. PRAGMA index_list/index_info(또는 PRAGMA table_info + index_list 조합)로 실제 유니크 제약을 확인하는 방식으로 바꿔 주세요.
```suggestion
	// 현재 테이블의 실제 유니크 인덱스 구조 확인 (UNIQUE(user_id, series_id) 가 있는지 체크)
	hasUniqueUserSeries := false

	indexRows, err := conn.QueryContext(ctx, "PRAGMA index_list('reading_progress')")
	if err != nil {
		return
	}
	defer indexRows.Close()

	for indexRows.Next() {
		var seq int
		var indexName string
		var unique int
		var origin string
		var partial int

		if err := indexRows.Scan(&seq, &indexName, &unique, &origin, &partial); err != nil {
			return
		}

		// 유니크 인덱스만 대상
		if unique != 1 {
			continue
		}

		// 해당 인덱스의 컬럼 목록 조회
		escapedName := strings.ReplaceAll(indexName, "'", "''")
		infoRows, err := conn.QueryContext(ctx, fmt.Sprintf("PRAGMA index_info('%s')", escapedName))
		if err != nil {
			return
		}

		var cols []string
		for infoRows.Next() {
			var seqno, cid int
			var colName string
			if err := infoRows.Scan(&seqno, &cid, &colName); err != nil {
				infoRows.Close()
				return
			}
			cols = append(cols, colName)
		}
		infoRows.Close()

		// 컬럼이 정확히 (user_id, series_id) 인 유니크 인덱스가 있는지 확인
		if len(cols) == 2 && cols[0] == "user_id" && cols[1] == "series_id" {
			hasUniqueUserSeries = true
			break
		}
	}

	if err := indexRows.Err(); err != nil {
		return
	}

	// 해당 유니크 인덱스가 없으면 마이그레이션 불필요
	if !hasUniqueUserSeries {
		return
	}
```

